import java.util.PriorityQueue

val vis = Array(110) { IntArray(110) }
val f = arrayOf(intArrayOf(0, 1), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(-1, 0))

class Node(var x: Int, var y: Int, var step: Int)

val q = PriorityQueue<Node>(compareBy { it.step })

fun bfs(l: Int, u: Int, xi: Int, yi: Int): Int {
    var e = Node(l, u, 0)
    q.add(e)
    vis[e.x][e.y] = 1
    while (q.isNotEmpty()) {
        e = q.poll()
        if (e.x == xi && e.y == yi) return e.step
        for (i in 0 until 4) {
            val t = Node(e.x + f[i][0], e.y + f[i][1], e.step + 1)
            if (t.x < 0 || t.y < 0) continue
            if (vis[t.x][t.y] != 0) continue
            vis[t.x][t.y] = 1
            q.add(t)
        }
    }
    return -1
}

fun main() {
    val s = readLine()!!.trim()
    val len = s.length
    var x = 0
    var y = 0
    var xx = 0
    var yy = 0
    for (i in 0 until len) {
        if (s[i] == 'L') y--
        if (s[i] == 'R') y++
        if (s[i] == 'U') x--
        if (s[i] == 'D') x++
        xx = minOf(xx, x)
        yy = minOf(yy, y)
    }
    xx = -xx
    yy = -yy
    for (i in 0 until 110) {
        for (j in 0 until 110) vis[i][j] = 1
    }
    x = xx
    y = yy
    for (i in 0 until len) {
        if (s[i] == 'L') y--
        if (s[i] == 'R') y++
        if (s[i] == 'U') x--
        if (s[i] == 'D') x++
        vis[x][y] = 0
    }
    val ans = bfs(xx, yy, x, y)

    if (ans == len) println("OK")
    else println("BUG")
}
